            .poll(async () => groupCount('No'), { timeout: 15000 })
            .toBe(initialNo);
        await expect
            .poll(async () => groupCount('Dunno'), { timeout: 15000 })
            .toBe(initialDunno);
        await expect
            .poll(async () => groupCount('None'), { timeout: 15000 })
            .toBe(noneAfterFirstUpdate);

        await expandGroup('Yes');
        await expect(playerRow).toBeVisible({ timeout: 10000 });
        await expect(
            playerRow.getByRole('checkbox', { name: /goalie/i }),
        ).toBeChecked();
        await expect(playerRow.getByPlaceholder('Comment')).toHaveValue(
            'Can play and cover goal first half',
        );

        await updatePlayer('No', false, 'Out of town this week');

        await expect
            .poll(async () => groupCount('Yes'), { timeout: 15000 })
            .toBe(yesAfterFirstUpdate - 1);
        await expect
            .poll(async () => groupCount('No'), { timeout: 15000 })
            .toBe(initialNo + 1);
        await expect
            .poll(async () => groupCount('Dunno'), { timeout: 15000 })
            .toBe(initialDunno);
        await expect
            .poll(async () => groupCount('None'), { timeout: 15000 })
            .toBe(noneAfterFirstUpdate);

        await expandGroup('No');
        await expect(playerRow).toBeVisible({ timeout: 10000 });
        await expect(
            playerRow.getByRole('checkbox', { name: /goalie/i }),
        ).not.toBeChecked();
        await expect(playerRow.getByPlaceholder('Comment')).toHaveValue(
            'Out of town this week',
        );

        await updatePlayer(
            'Dunno',
            false,
            'Could make it if meeting ends early',
        );

        await expect
            .poll(async () => groupCount('Yes'), { timeout: 15000 })
            .toBe(yesAfterFirstUpdate - 1);
        await expect
            .poll(async () => groupCount('No'), { timeout: 15000 })
            .toBe(initialNo);
        await expect
            .poll(async () => groupCount('Dunno'), { timeout: 15000 })
            .toBe(initialDunno + 1);
        await expect
            .poll(async () => groupCount('None'), { timeout: 15000 })
            .toBe(noneAfterFirstUpdate);

        await expandGroup('Dunno');
        await expect(playerRow).toBeVisible({ timeout: 10000 });
        await expect(
            playerRow.getByRole('checkbox', { name: /goalie/i }),
        ).not.toBeChecked();
        await expect(playerRow.getByPlaceholder('Comment')).toHaveValue(
            'Could make it if meeting ends early',
        );

        await updatePlayer('Yes', true, 'Back in: definitely available');

        await expect
            .poll(async () => groupCount('Yes'), { timeout: 15000 })
            .toBe(yesAfterFirstUpdate);
        await expect
            .poll(async () => groupCount('No'), { timeout: 15000 })
            .toBe(initialNo);
        await expect
            .poll(async () => groupCount('Dunno'), { timeout: 15000 })
            .toBe(initialDunno);
        await expect
            .poll(async () => groupCount('None'), { timeout: 15000 })
            .toBe(noneAfterFirstUpdate);
    });
});

